3	public sealed class BaselineEvaluator(NormalityOptions normalityOptions) : IBaselineEvaluator
4	{
5	    // Scales a MAD so it is comparable with a standard deviation.
6	    private const double MadConsistencyConstant = 1.4826;
7	    private const double AnscombeOffset = 0.375;
8	    private const double AnscombeScale = 2.0;
9	
10	    private static readonly double TransformedZero = AnscombeTransform(0);
11	
12	    public SeriesHealth Evaluate(IReadOnlyList<int> eligibleWeekCounts, int selectedWeekCount)
13	    {
14	        if (eligibleWeekCounts.Count < normalityOptions.MinimumEligibleWeeks)
15	        {
16	            return new SeriesHealth(
17	                selectedWeekCount,
18	                new Baseline(eligibleWeekCounts.Count, null, null, null),
19	                HealthStatus.InsufficientData,
20	                null);
21	        }
22	
23	        var median = MedianOf(eligibleWeekCounts.Select(count => (double)count));
24	        var centre = AnscombeTransform(median);
25	        var spread = SpreadOf(eligibleWeekCounts, centre);
26	        var (low, high) = RangeFor(centre, spread);
27	
28	        return new SeriesHealth(
29	            selectedWeekCount,
30	            new Baseline(eligibleWeekCounts.Count, median, low, high),
31	            StatusFor(selectedWeekCount, low, high),
32	            DeviationOf(selectedWeekCount, centre, spread));
33	    }
34	
35	    private static double AnscombeTransform(double count) => AnscombeScale * Math.Sqrt(count + AnscombeOffset);
36	
37	    private static double InverseAnscombeTransform(double transformed)
38	    {
39	        var root = transformed / AnscombeScale;
40	        return root * root - AnscombeOffset;
41	    }
42	
43	    private static double MedianOf(IEnumerable<double> values)
44	    {
45	        var sortedValues = values.Order().ToList();
46	        var middleIndex = sortedValues.Count / 2;
47	        return sortedValues.Count % 2 == 1
48	            ? sortedValues[middleIndex]
49	            : (sortedValues[middleIndex - 1] + sortedValues[middleIndex]) / 2.0;
50	    }
51	
52	    private double SpreadOf(IReadOnlyList<int> eligibleWeekCounts, double centre)
53	    {
54	        var madT = MedianOf(eligibleWeekCounts.Select(count => Math.Abs(AnscombeTransform(count) - centre)));
55	        return Math.Max(MadConsistencyConstant * madT, normalityOptions.SpreadFloor);
56	    }
57	
58	    private (int Low, int High) RangeFor(double centre, double spread)
59	    {
60	        var lowT = centre - normalityOptions.BandWidth * spread;
61	        var highT = centre + normalityOptions.BandWidth * spread;
62	        var low = lowT <= TransformedZero ? 0 : (int)Math.Ceiling(InverseAnscombeTransform(lowT));
63	        var high = (int)Math.Floor(InverseAnscombeTransform(highT));
64	        return (low, high);
65	    }
66	
67	    private static HealthStatus StatusFor(int selectedWeekCount, int low, int high)
68	    {
69	        if (selectedWeekCount < low)
70	        {
71	            return HealthStatus.Below;
72	        }
73	
74	        return selectedWeekCount > high ? HealthStatus.Above : HealthStatus.Normal;
75	    }
76	
77	    private static double DeviationOf(int selectedWeekCount, double centre, double spread) =>
78	        (AnscombeTransform(selectedWeekCount) - centre) / spread;
79	}
